    <td>数据变更时触发</td>
  </tr>
  <tr>
    <td>`DataEvent.onValueInit`</td>
    <td>数据初始化时触发</td>
  </tr>
  <tr>
    <td>`DataEvent.onValueInitOrChange`</td>
